{"items":[{"id":"cap-v2-callbacks_and_events-java-repair-01","test_code":"import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testMixedStatementsAndCallbackOrder();
        testExactBatchBoundary();
        testEmptyInput();
        testAllMalformed();
    }

    private static void testMixedStatementsAndCallbackOrder() {
        String[] input = {" a ", " ", null, "b", "c", "\t", "d"};
        String[] original = input.clone();
        List<String> events = new ArrayList<>();

        Solution.submit(input, 2, new Solution.BatchListener() {
            public void onBatch(List<String> statements) {
                events.add("B:" + new ArrayList<>(statements));
                assertTrue(statements.size() <= 2, "batch exceeded maximum size");
            }

            public void onRejected(int index, String statement) {
                events.add("R:" + index + ":" + String.valueOf(statement));
            }
        }, (accepted, rejected) -> events.add("C:" + accepted + ":" + rejected));

        assertListEquals(Arrays.asList(
                "R:1: ",
                "R:2:null",
                "B:[ a , b]",
                "R:5:\t",
                "B:[c, d]",
                "C:4:3"), events, "mixed statements");
        assertTrue(Arrays.equals(original, input), "input array was mutated");
    }

    private static void testExactBatchBoundary() {
        List<String> events = new ArrayList<>();
        Solution.submit(new String[]{"x", "y", "z"}, 3, listener(events),
                (accepted, rejected) -> events.add("C:" + accepted + ":" + rejected));

        assertListEquals(Arrays.asList("B:[x, y, z]", "C:3:0"), events,
                "exact batch boundary");
    }

    private static void testEmptyInput() {
        List<String> events = new ArrayList<>();
        Solution.submit(new String[0], 1, listener(events),
                (accepted, rejected) -> events.add("C:" + accepted + ":" + rejected));

        assertListEquals(Arrays.asList("C:0:0"), events, "empty input");
    }

    private static void testAllMalformed() {
        List<String> events = new ArrayList<>();
        Solution.submit(new String[]{null, "", "   ", "\n"}, 2, listener(events),
                (accepted, rejected) -> events.add("C:" + accepted + ":" + rejected));

        assertListEquals(Arrays.asList(
                "R:0:null", "R:1:", "R:2:   ", "R:3:\n", "C:0:4"),
                events, "all malformed");
    }

    private static Solution.BatchListener listener(List<String> events) {
        return new Solution.BatchListener() {
            public void onBatch(List<String> statements) {
                events.add("B:" + new ArrayList<>(statements));
            }

            public void onRejected(int index, String statement) {
                events.add("R:" + index + ":" + String.valueOf(statement));
            }
        };
    }

    private static void assertListEquals(List<String> expected, List<String> actual,
                                         String context) {
        if (!expected.equals(actual)) {
            throw new AssertionError(context + " expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
