{"items":[{"id":"cap-v2-graph_and_tree-java-repair-02","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testInvocationIsolation();
        testForestAndNonMutation();
        testNegativeAndBoundaryValues();
        testSingleNode();
    }

    private static void testInvocationIsolation() {
        assertArrayEquals(
                new int[]{6, 2, 3},
                Solution.subtreeSums(new int[]{-1, 0, 0}, new int[]{1, 2, 3}),
                "first invocation");

        assertArrayEquals(
                new int[]{2, 6, 7},
                Solution.subtreeSums(new int[]{-1, -1, -1}, new int[]{2, 6, 7}),
                "later invocation must not retain old children");
    }

    private static void testForestAndNonMutation() {
        int[] parent = {-1, 0, 0, -1, 3, 1};
        int[] value = {5, 2, -3, 10, 4, 7};
        int[] originalParent = parent.clone();
        int[] originalValue = value.clone();

        int[] actual = Solution.subtreeSums(parent, value);

        assertArrayEquals(new int[]{11, 9, -3, 14, 4, 7}, actual, "multi-root forest");
        assertArrayEquals(originalParent, parent, "parent array was modified");
        assertArrayEquals(originalValue, value, "value array was modified");
    }

    private static void testNegativeAndBoundaryValues() {
        assertArrayEquals(
                new int[]{0, -Integer.MAX_VALUE},
                Solution.subtreeSums(
                        new int[]{-1, 0},
                        new int[]{Integer.MAX_VALUE, -Integer.MAX_VALUE}),
                "boundary values whose subtree sums fit in int");
    }

    private static void testSingleNode() {
        assertArrayEquals(
                new int[]{Integer.MIN_VALUE},
                Solution.subtreeSums(new int[]{-1}, new int[]{Integer.MIN_VALUE}),
                "single-node forest");
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }
}
